import React from 'react'

const SuccessMessage = ({formData}) => {

        const clickHandler = (event) => {
                event.preventDefault();
                setFormSubmitted(true);
                // Handle form submission (e.g., send data to backend)
                console.log(formData);
              //  navigate('/takequiz');
        };

        return (
                <div>
                        <h2 className="text-3xl font-bold mb-4">Quiz Created Successfully!</h2>
                        <h4 className="text-xl mb-2">Quiz Details:</h4>

                        <p><strong>Name:</strong> {formData.name}</p>
                        <p><strong>Exam:</strong> {formData.exam}</p>
                        <p><strong>Difficulty Levels:</strong> {formData.difficultyLevels.join(', ')}</p>
                        <p><strong>Class / Year:</strong> {formData.classYear}</p>
                        <p><strong>Subjects:</strong>{formData.subjects.join(', ')}</p>
                        <p><strong>Topics:</strong>{formData.subjects.join(', ')}</p>
                        <p><strong>Quiz Mode:</strong> {formData.quizMode}</p>
                        <p><strong>Number of Questions:</strong> {formData.numberOfQuestions}</p>

                        {formData.addHints && <p><strong>Hints:</strong> Enabled</p>}
                        {formData.answerExplanation? <p><strong>Answer Explanation:</strong> Enabled</p> : <p><strong>Answer Explanation:</strong>Disabled</p>}
                        {formData.breakIntoSubtopics? <p><strong>Break Into Subtopics:</strong> Enabled</p> : <p><strong>Break Into Subtopics:</strong>Disabled</p>}

                        <div className="mt-4">
                                <button
                                        className="bg-green-500 text-white py-2 px-4 rounded-lg"
                                        onClick={clickHandler} 
                                >
                                        Start Quiz
                                </button>
                        </div>

                        <div className="mt-4">
                                <button
                                        className="bg-green-500 text-white py-2 px-4 rounded-lg"
                                        onClick={() => window.location.reload()} // Optionally reload or reset the form
                                >
                                        Create Another Quiz
                                </button>
                        </div>

                </div>
        )

}

export default SuccessMessage
